// Arma la respuesta de la API: el saldo en AVAX de la dirección pedida.
// La dirección llega en la URL (?address=0x...) o, en la prueba manual, desde «Dirección de ejemplo».
const pedido = $('Consulta por URL').isExecuted
  ? $('Consulta por URL').first().json
  : $('Dirección de ejemplo').first().json;
const direccion = String((pedido.query || {}).address || '').trim().toLowerCase();
const respuesta = $input.first().json;

// 1 AVAX = 10^18 wei. BigInt divide sin perder decimales (Number los perdería).
function enAVAX(wei) {
  const base = 10n ** 18n;
  const resto = (wei % base).toString().padStart(18, '0').replace(/0+$/, '');
  return resto ? `${wei / base}.${resto}` : `${wei / base}`;
}

if (!/^0x[0-9a-f]{40}$/.test(direccion)) {
  return [{ json: { ok: false, tipoError: 'direccion', error: 'Mandá una dirección de la C-Chain en ?address= : 0x y 40 caracteres hexadecimales.', direccion } }];
}
if (respuesta.error || typeof respuesta.result !== 'string') {
  const detalle = respuesta.error?.message ?? JSON.stringify(respuesta.error ?? respuesta);
  return [{ json: { ok: false, tipoError: 'rpc', error: `El RPC de Fuji no respondió bien (${detalle}). Esperá un momento y probá de nuevo.`, direccion } }];
}

const wei = BigInt(respuesta.result);
return [
  {
    json: {
      ok: true,
      red: 'Avalanche Fuji C-Chain',
      direccion,
      saldoAVAX: enAVAX(wei),
      saldoWei: wei.toString(),
      consultado: $now.setZone('America/La_Paz').toFormat('dd/MM/yyyy HH:mm:ss'),
      explorador: `https://build.avax.network/explorer/fuji/c-chain/address/${direccion}`,
    },
  },
];

// La misma cuenta que en la API, pero el resultado se arma para la página final del formulario.
const direccion = String($('Formulario de saldo').first().json.address || '').trim().toLowerCase();
const respuesta = $input.first().json;

function enAVAX(wei) {
  const base = 10n ** 18n;
  const resto = (wei % base).toString().padStart(18, '0').replace(/0+$/, '');
  return resto ? `${wei / base}.${resto}` : `${wei / base}`;
}

if (!/^0x[0-9a-f]{40}$/.test(direccion)) {
  return [{ json: { ok: false, titulo: 'Revisá la dirección', mensaje: 'Una dirección de la C-Chain empieza con 0x y tiene 40 caracteres más (números y letras de la a a la f). Volvé atrás y probá de nuevo.' } }];
}
if (respuesta.error || typeof respuesta.result !== 'string') {
  return [{ json: { ok: false, titulo: 'Fuji no respondió', mensaje: 'El RPC público de Fuji no respondió bien. Esperá un momento y probá de nuevo.' } }];
}

const saldo = enAVAX(BigInt(respuesta.result));
return [
  {
    json: {
      ok: true,
      direccion,
      saldoAVAX: saldo,
      titulo: `${saldo} AVAX`,
      mensaje: `Es el saldo de ${direccion} en Avalanche Fuji, la red de prueba (son AVAX sin valor real). Miralo en el explorador: https://build.avax.network/explorer/fuji/c-chain/address/${direccion}`,
    },
  },
];
